<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#000000;--bg-card:#141414;--bg-elevated:#1a1a1a;
  --red:#E50914;--red-hover:#c4070f;--red-glow:rgba(229,9,20,.35);
  --white:#ffffff;--gray-100:#e5e5e5;--gray-300:#b3b3b3;--gray-500:#737373;--gray-700:#404040;--gray-900:#1a1a1a;
