.hero-mosaic-tile{background:var(--gray-700);border-radius:6px;position:relative;overflow:hidden}
.hero-mosaic-tile::after{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(229,9,20,.15),rgba(0,0,0,.4))}
.hero-mosaic-tile:nth-child(odd){background:var(--gray-900)}
.hero-mosaic-tile:nth-child(3n){background:#1c0506}
.hero-overlay{position:absolute;inset:0;background:radial-gradient(ellipse at center,rgba(0,0,0,.4) 0%,rgba(0,0,0,.85) 75%,#000 100%);z-index:1}
